import Foundation
import AppCore

/// String lookup that follows the in-app 地區介面 setting instead of only the device language.
///
/// Keys are the Hong Kong strings (development language). `Localizable.strings` lives in
/// `App/zh-Hant-HK.lproj` and `App/zh-Hant-TW.lproj`, generated by `scripts/gen_l10n.py`.
/// Lookups go to the chosen `.lproj` bundle directly, which works on iOS 16 without
/// relaunching the app. A missing key falls back to the Hong Kong key text. A key may carry a
/// context suffix (`"完場|nav"`) when Taiwan needs a different word for the same HK text.
enum L10n {
    private static let lock = NSLock()
    private static var storedRegion: InterfaceRegion = .hongKong
    private static var bundleCache: [InterfaceRegion: Bundle] = [:]

    /// Region used by `tr(_:)`. Set by `AppViewModel.refreshRegion()`.
    static var region: InterfaceRegion {
        get { lock.lock(); defer { lock.unlock() }; return storedRegion }
        set { lock.lock(); storedRegion = newValue; lock.unlock() }
    }

    /// Region for 跟系統: device language zh-Hant-TW or device region TW → Taiwan, else Hong Kong.
    static var systemRegion: InterfaceRegion {
        let regionCode = Locale.current.region?.identifier
        return InterfaceRegion.detect(preferredLanguages: Locale.preferredLanguages, regionCode: regionCode)
    }

    static func bundle(for region: InterfaceRegion) -> Bundle {
        lock.lock(); defer { lock.unlock() }
        if let cached = bundleCache[region] { return cached }
        let bundle = Bundle.main.path(forResource: region.localizationIdentifier, ofType: "lproj")
            .flatMap(Bundle.init(path:)) ?? .main
        bundleCache[region] = bundle
        return bundle
    }

    static func string(_ key: String, region: InterfaceRegion) -> String {
        // Context keys look like "完場|nav"; if a lookup ever misses, show the text before "|".
        let fallback = key.split(separator: "|", maxSplits: 1).first.map(String.init) ?? key
        return bundle(for: region).localizedString(forKey: key, value: fallback, table: "Localizable")
    }
}

/// Localized string for the current 地區介面.
func tr(_ key: String) -> String {
    L10n.string(key, region: L10n.region)
}

/// Localized format string for the current 地區介面. Keys use `%@` placeholders; pass strings.
func tr(_ key: String, _ arguments: String...) -> String {
    let region = L10n.region
    return String(format: L10n.string(key, region: region), locale: region.locale, arguments: arguments)
}
